    pub mod list_configs {
        use crate::{Endian, Error, TlvBuf, TlvReader, TlvWriter};
        use alloc::string::String;
        use alloc::vec::Vec;
        pub const MESSAGE_ID: u16 = 36;
        #[derive(Debug, Clone, PartialEq, Default)]
        pub struct Indication {}
        impl Indication {
            pub fn to_tlvs(&self) -> Result<Vec<TlvBuf>, Error> {
                Ok(Vec::new())
            }
            pub fn from_tlvs(_tlvs: &[TlvBuf]) -> Result<Self, Error> {
                Ok(Self::default())
            }
        }
        #[derive(Debug, Clone, PartialEq, Default)]
        pub struct Element {
            pub config_type: u32,
            pub id: Vec<u8>,
        }
        impl Element {
            pub fn encode_to(&self, writer: &mut TlvWriter) -> Result<(), Error> {
                writer.write_u32(*&self.config_type, Endian::Little);
                writer.write_u8(u8::try_from((&self.id).len()).map_err(|_| Error::TooLong)?);
                for item in &self.id {
                    writer.write_u8(*item);
                }
                Ok(())
            }
            pub fn decode_from(reader: &mut TlvReader<'_>) -> Result<Self, Error> {
                let mut out = Self::default();
                out.config_type = reader.read_u32(Endian::Little)?;
                let count = reader.read_u8()? as usize;
                let mut items = Vec::with_capacity(count.min(256));
                for _ in 0..count {
                    items.push(reader.read_u8()?);
                }
                out.id = items;
                Ok(out)
            }
        }
    }
